<template>
  <aside class="assistant">
    <div class="head"><div class="assistant-title"><span class="assistant-icon"><Sparkles :size="19" /></span><div><small>AI ASSISTANT</small><h2>教学助手</h2></div></div><button class="mobile" @click="$emit('close')">返回教案</button></div>
    <div class="context"><strong>参考资料</strong><button :disabled="!ready" @click="$emit('sources')">{{ sourceCount ? `已选择 ${sourceCount} 项 · 调整` : '未选择 · 选择资料' }}</button><p v-if="!ready">请先上传或粘贴教案，再选择参考资料或开始分析。</p><p v-else-if="sourceCount">所选资料的检索尚未接入，请清除并保存后使用通用分析。</p><p v-else>未使用参考资料，结果为通用模型建议，请教师核实。</p></div>
    <div class="conversation" aria-live="polite"><div class="bubble intro"><strong>从这里开始</strong><p>可以让我分析整份教案，或先在正文中选中一段，再告诉我如何优化。</p></div><div v-if="selectedText" class="selection"><strong>已选中正文</strong><p>{{ selectedText }}</p></div><template v-if="response"><div class="bubble"><span class="result-label">分析建议 · 通用模型</span><p>{{ response.analysis }}</p></div><div v-if="response.suggestion" class="proposal"><span class="result-label">修改建议</span><div v-if="response.selection" class="comparison-original"><small>修改前</small><p>{{ response.selection }}</p></div><label><small>建议修改 · 可继续调整</small><textarea v-model="response.suggestion" rows="5" aria-label="建议修改内容"></textarea></label><div class="proposal-actions"><button v-if="response.selection" ref="compareTrigger" @click="compareOpen = true">查看修改对比</button><button v-if="response.selection" :disabled="dirty || stale || locked || !response.suggestion.trim()" @click="$emit('apply', response.suggestion, response.selection, response.selectionKey)">采纳到所选位置</button></div><small v-if="locked">教案已锁定，不能采纳修改。</small><small v-if="stale">教案版本已变化，请重新生成建议。</small><small v-else-if="saving">正在保存修改，完成后可继续优化。</small><small v-else-if="dirty">正文有未保存的修改，请保存后重新生成建议。</small></div></template><p v-if="error" class="error" role="alert">{{ error }}</p></div>
    <div class="composer"><textarea v-model="instruction" rows="3" placeholder="输入问题或修改要求，例如：让选中段落更适合四年级学生" aria-label="向教学助手提问"></textarea><div><button :disabled="!ready || loading || saving || dirty || sourceCount > 0" @click="run('分析整份教案')">{{ loading ? '正在分析…' : '分析教案' }}</button><button class="primary" :disabled="!ready || loading || saving || dirty || sourceCount > 0 || !instruction.trim()" @click="run(instruction)">发送</button></div><small v-if="!ready">请先导入教案。</small><small v-else-if="saving">正在保存修改，完成后可继续优化。</small><small v-else-if="dirty">请先保存修改，再进行分析。</small><small v-else>模型可能出错，采纳前请核实。</small></div>
    <Teleport to="body"><div v-if="compareOpen && response" class="compare-backdrop" @click.self="compareOpen = false" @keydown.esc="compareOpen = false"><section class="compare-dialog" role="dialog" aria-modal="true" aria-labelledby="compare-title"><div class="compare-head"><div><small>REVISION PREVIEW</small><h2 id="compare-title">查看修改对比</h2></div><button ref="compareClose" aria-label="关闭" @click="compareOpen = false">×</button></div><p class="compare-reason">{{ response.analysis }}</p><div class="compare-grid"><div><strong>修改前</strong><p>{{ difference.prefix }}<del>{{ difference.removed }}</del>{{ difference.suffix }}</p></div><div><strong>修改后</strong><p>{{ difference.prefix }}<ins>{{ difference.added }}</ins>{{ difference.suffix }}</p><label for="compare-suggestion">继续调整建议</label><textarea id="compare-suggestion" v-model="response.suggestion" rows="5"></textarea></div></div><p class="compare-note">未使用参考资料；请结合课堂实际核实建议。</p><div class="compare-actions"><button @click="compareOpen = false">取消</button><button class="compare-primary" :disabled="dirty || stale || locked || !response.suggestion.trim()" @click="acceptComparison">采纳修改</button></div></section></div></Teleport>
  </aside>
</template>
<script setup lang="ts">
import {computed, nextTick, ref, watch} from 'vue';
import {Sparkles} from 'lucide-vue-next';
import {json, request} from './api';
const props = defineProps<{ready:boolean; workspaceId:string; artifactId:string; version:number; dirty:boolean; saving:boolean; locked:boolean; sourceCount:number; selectedText:string; selectionKey:string}>();
const emit = defineEmits<{close:[]; sources:[]; apply:[text:string, selection:string, selectionKey:string]}>();
const instruction = ref(''), loading = ref(false), error = ref(''), compareOpen = ref(false);
const compareTrigger = ref<HTMLButtonElement | null>(null), compareClose = ref<HTMLButtonElement | null>(null);
watch(compareOpen, async open => { await nextTick(); if (open) compareClose.value?.focus(); else compareTrigger.value?.focus(); });
const response = ref<{analysis:string; suggestion:string; selection:string; selectionKey:string; version:number} | null>(null);
const difference = computed(() => { const before = Array.from(response.value?.selection || ''), after = Array.from(response.value?.suggestion || ''); let start = 0, end = 0; while (start < before.length && start < after.length && before[start] === after[start]) start++; while (end < before.length - start && end < after.length - start && before[before.length - 1 - end] === after[after.length - 1 - end]) end++; return {prefix:before.slice(0, start).join(''), removed:before.slice(start, before.length - end).join(''), added:after.slice(start, after.length - end).join(''), suffix:end ? before.slice(-end).join('') : ''}; });
const stale = computed(() => !!response.value && response.value.version !== props.version);
watch(() => props.sourceCount, () => { response.value = null; compareOpen.value = false; });
function acceptComparison() { if (!response.value || props.dirty || stale.value || props.locked || !response.value.suggestion.trim()) return; emit('apply', response.value.suggestion, response.value.selection, response.value.selectionKey); compareOpen.value = false; }
async function run(command:string) { if (!props.ready || loading.value || props.saving || props.dirty || props.sourceCount) return; loading.value = true; error.value = ''; const selection = command === '分析整份教案' ? '' : props.selectedText; const key = props.selectionKey; const version = props.version; try { const result = await request<{analysis:string;suggestion:string}>(`/api/inquiry-workspaces/${encodeURIComponent(props.workspaceId)}/lesson-document/${encodeURIComponent(props.artifactId)}/assistant`, json('POST', {expected_version:version,instruction:command,selected_text:selection})); response.value = {...result,selection,selectionKey:key,version}; } catch(e) { error.value = e instanceof Error ? e.message : '分析失败，请重试。'; } finally { loading.value = false; } }
</script>
<style scoped>
