ng:11px;border:1px solid var(--studio-line);border-radius:10px;background:var(--studio-subtle);font:inherit}.composer>div{display:flex;justify-content:space-between;gap:8px;margin:10px 0}.assistant button{font:inherit;background:white;border:1px solid var(--studio-line);color:var(--studio-ink);border-radius:10px;padding:8px 11px;cursor:pointer;font-weight:650}.assistant button:hover:not(:disabled){border-color:#8fc9a6}.assistant button:focus-visible,.assistant textarea:focus-visible{outline:3px solid #8fc9a6;outline-offset:2px}.assistant button:disabled{opacity:.5;cursor:not-allowed}.assistant .primary{background:var(--studio-green);border-color:var(--studio-green);color:white}.mobile{display:none}@media(max-width:700px){.assistant{position:static;height:auto;min-height:65vh}.mobile{display:block}}
